<template>
  <CrudShell title="Quản lý product" :loading="loading" :error="error" @create="openCreate" @reload="load">
    <template #form v-if="editing"><form class="space-y-4 rounded-3xl border bg-white p-4" @submit.prevent="save"><div class="grid gap-3 md:grid-cols-3"><input v-model="form.name" class="rounded-xl border p-3" placeholder="Name"><input v-model="form.slug" class="rounded-xl border p-3" placeholder="Slug"><input v-model="form.categoryId" class="rounded-xl border p-3" placeholder="Category ID"><input v-model="form.shortDescription" class="rounded-xl border p-3 md:col-span-2" placeholder="Short description"><select v-model="form.status" class="rounded-xl border p-3"><option>ACTIVE</option><option>INACTIVE</option><option>DRAFT</option></select><label class="flex items-center gap-2 rounded-xl border p-3"><input v-model="form.isFeatured" type="checkbox"> Featured</label><input v-model.number="form.featuredOrder" class="rounded-xl border p-3" placeholder="Featured order"><FileUpload v-model="uploaded" scope="admin" accept="image/*" title="Upload product image" @uploaded="addImage" /></div><EditorJsField v-model="form.descriptionJson" /><div><h3 class="mb-2 font-black">Images</h3><div class="grid gap-2 md:grid-cols-3"><div v-for="(image, i) in imageList" :key="i" class="rounded-xl border p-3"><input v-model="image.fileId" class="mb-2 w-full rounded border p-2" placeholder="fileId"><input v-model="image.altText" class="mb-2 w-full rounded border p-2" placeholder="alt"><label><input v-model="image.isPrimary" type="checkbox"> Primary</label></div></div><button type="button" class="mt-2 rounded-xl border px-3 py-2" @click="addEmptyImage">+ Image</button></div><div><h3 class="mb-2 font-black">Variants</h3><div class="grid gap-2 md:grid-cols-2"><div v-for="variant in form.variants" :key="variant.clientId || variant.id" class="grid gap-2 rounded-xl border p-3"><input v-model="variant.name" class="rounded border p-2" placeholder="Name"><input v-model="variant.colorName" class="rounded border p-2" placeholder="Color name"><input v-model="variant.colorCode" class="rounded border p-2" placeholder="#000000"><select v-model="variant.status" class="rounded border p-2"><option>ACTIVE</option><option>INACTIVE</option></select></div></div><button type="button" class="mt-2 rounded-xl border px-3 py-2" @click="addVariant">+ Variant</button></div><div><h3 class="mb-2 font-black">SKUs</h3><div class="grid gap-2 md:grid-cols-2"><div v-for="sku in form.skus" :key="sku.skuCode" class="grid gap-2 rounded-xl border p-3"><input v-model="sku.variantClientId" class="rounded border p-2" placeholder="variantClientId"><input v-model="sku.skuCode" class="rounded border p-2" placeholder="SKU code"><input v-model="sku.size" class="rounded border p-2" placeholder="Size"><input v-model.number="sku.price" class="rounded border p-2" placeholder="Price"><input v-model.number="sku.salePrice" class="rounded border p-2" placeholder="Sale price"><input v-model.number="sku.stock" class="rounded border p-2" placeholder="Stock"></div></div><button type="button" class="mt-2 rounded-xl border px-3 py-2" @click="addSku">+ SKU</button></div><div class="flex gap-2"><button class="rounded-xl bg-slate-950 px-4 py-2 font-bold text-white">Save</button><button type="button" class="rounded-xl border px-4 py-2" @click="editing = null">Cancel</button></div></form></template>
    <table class="w-full text-left text-sm"><thead><tr class="border-b"><th class="p-3">Name</th><th>Slug</th><th>Status</th><th>Featured</th><th>Price</th><th></th></tr></thead><tbody><tr v-for="row in rows" :key="row.id" class="border-b"><td class="p-3 font-bold">{{ row.name }}</td><td>{{ row.slug }}</td><td>{{ row.status }}</td><td>{{ row.isFeatured ? 'Yes' : 'No' }}</td><td>{{ money(row.salePrice || row.price) }}</td><td class="space-x-2 text-right"><button class="font-bold" @click="openEdit(row.id)">Edit</button><button class="font-bold text-red-600" @click="remove(row.id)">Delete</button></td></tr></tbody></table>
  </CrudShell>
</template>
<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import CrudShell from '@/pages/admin/CrudShell.vue'
import EditorJsField from '@/components/editor/EditorJsField.vue'
import FileUpload from '@/components/common/FileUpload.vue'
import { productApi } from '@/modules/catalog/product/api'
import { getErrorMessage } from '@/modules/shared/hooks'
import { money } from '@/modules/shared/types'
import type { Product, ProductPayload } from '@/modules/catalog/product/types'
import type { UploadedFile } from '@/services/file.service'
const rows = ref<Product[]>([]); const loading = ref(false); const error = ref(''); const editing = ref<Product | 'new' | null>(null); const uploaded = ref<UploadedFile | null>(null)
const form = reactive<ProductPayload>({ categoryId: '', name: '', slug: '', shortDescription: '', descriptionJson: { blocks: [] }, status: 'ACTIVE', isFeatured: false, featuredOrder: 0, images: [], variants: [], skus: [] })
const imageList = computed(() => ensureImages())
function reset(row?: Product) { form.categoryId = row?.categoryId || ''; form.name = row?.name || ''; form.slug = row?.slug || ''; form.shortDescription = row?.shortDescription || ''; form.descriptionJson = row?.descriptionJson || { blocks: [] }; form.status = row?.status || 'ACTIVE'; form.isFeatured = !!row?.isFeatured; form.featuredOrder = row?.featuredOrder || 0; form.images = [...(row?.images || [])]; form.variants = [...(row?.variants || [])]; form.skus = [...(row?.skus || [])] }
function openCreate() { editing.value = 'new'; reset() } async function openEdit(id: string) { const row = await productApi.adminDetail(id); editing.value = row; reset(row) }
function ensureImages() { form.images ||= []; return form.images }
function ensureVariants() { form.variants ||= []; return form.variants }
function ensureSkus() { form.skus ||= []; return form.skus }
function addVariant() { const variants = ensureVariants(); const clientId = crypto.randomUUID(); variants.push({ clientId, name: '', colorName: '', colorCode: '#000000', status: 'ACTIVE', sortOrder: variants.length }) }
function addSku() { const variants = ensureVariants(); ensureSkus().push({ variantClientId: variants[0]?.clientId, skuCode: '', size: '', price: 0, salePrice: null, stock: 0, status: 'ACTIVE' }) }
function addImage(file: UploadedFile) { const images = ensureImages(); images.push({ fileId: String(file.fileId), altText: form.name, imageType: images.length ? 'GALLERY' : 'MAIN', sortOrder: images.length, isPrimary: images.length === 0 }) }
function addEmptyImage() { const images = ensureImages(); images.push({ imageType: 'GALLERY', sortOrder: images.length, isPrimary: false }) }
async function load() { loading.value = true; try { rows.value = (await productApi.adminList({ limit: 50 })).items } catch (err) { error.value = getErrorMessage(err) } finally { loading.value = false } }
async function save() { try { if (editing.value === 'new') await productApi.create(form); else if (editing.value) await productApi.update(editing.value.id, form); editing.value = null; await load() } catch (err) { error.value = getErrorMessage(err) } }
async function remove(id: string) { if (!confirm('Delete product?')) return; await productApi.remove(id); await load() }
onMounted(load)
</script>
